(()=>{'use strict';
const words={title:['受邀工作人員登入（TEST）','Invited staff login (TEST)','आमन्त्रित कर्मचारी लगइन (परीक्षण)'],boundary:['隔離虛構演練。正式投票、收款與身分文件收件尚未開放。','Isolated fictional rehearsal. Official voting, payments and identity-document collection are not open.','छुट्टै काल्पनिक अभ्यास। आधिकारिक मतदान, भुक्तानी र परिचयपत्र सङ्कलन खुलेका छैनन्।'],email:['受邀 Email','Invited email','आमन्त्रित इमेल'],role:['登入身分','Staff role','कर्मचारीको भूमिका'],organizer:['主辦單位','Organizer','आयोजक'],reviewer:['評審','Judge','निर्णायक'],send:['寄送驗證碼','Send code','कोड पठाउनुहोस्'],retry:['重新載入真人驗證','Reload human verification','मानव प्रमाणीकरण फेरि लोड गर्नुहोस्'],code:['6 位驗證碼','Six-digit code','छ अङ्कको कोड'],verify:['驗證登入','Verify and sign in','प्रमाणित गरी लगइन गर्नुहोस्'],change:['更換 Email／身分','Change email / role','इमेल / भूमिका बदल्नुहोस्'],stage:['前往決賽評審演練','Open final judging rehearsal','फाइनल मूल्याङ्कन अभ्यास खोल्नुहोस्'],vote:['前往決賽投票管理演練','Open ballot administration rehearsal','फाइनल मतदान व्यवस्थापन अभ्यास खोल्नुहोस्'],logout:['登出','Sign out','बाहिरिनुहोस्'],human:['請完成真人驗證。','Complete human verification.','मानव प्रमाणीकरण पूरा गर्नुहोस्।'],sent:['若此信箱已受邀，請查收驗證碼；10 分鐘內有效。','If invited, check your mailbox. The code expires in ten minutes.','आमन्त्रित भए इमेल जाँच्नुहोस्। कोड दस मिनेटमा म्याद सकिन्छ।'],failed:['目前無法完成，請重新查核或載入真人驗證。','Unable to complete. Check again or reload verification.','कार्य पूरा भएन। फेरि जाँच्नुहोस् वा प्रमाणीकरण लोड गर्नुहोस्।'],invalid:['驗證碼錯誤或已過期，請重新取得。','Code incorrect or expired. Request a new code.','कोड गलत वा म्याद सकिएको छ। नयाँ कोड लिनुहोस्।'],signed:['已驗證受邀工作人員身分。','Invited staff session verified.','आमन्त्रित कर्मचारी सत्र प्रमाणित भयो।'],signedout:['已登出，請重新驗證。','Signed out. Verify again to sign in.','बाहिरिनुभयो। फेरि लगइन गर्न प्रमाणित गर्नुहोस्।']};
let lang='zh',token='',challenge=null,busy=false,widget=null,identity=null,epoch=0,statusKey='';
const $=id=>document.getElementById(id),t=key=>words[key]?.[['zh','en','ne'].indexOf(lang)]||key;
function message(key){statusKey=key;$('staff-status').textContent=t(key)}
function translated(){document.documentElement.lang={zh:'zh-Hant',en:'en',ne:'ne'}[lang];$('staff-title').textContent=t('title');$('staff-boundary').textContent=t('boundary');document.querySelectorAll('[data-word]').forEach(e=>e.textContent=t(e.dataset.word));if(identity)$('staff-role-status').textContent=t(identity.role);if(statusKey)$('staff-status').textContent=t(statusKey)}
function buttons(){for(const id of ['staff-verify','staff-change','staff-logout','staff-retry'])$(id).disabled=busy;$('staff-send').disabled=busy||!token}
async function api(path,body){const r=await fetch('/api/e2e/'+path,{method:body?'POST':'GET',credentials:'same-origin',cache:'no-store',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined,signal:AbortSignal.timeout(15000)});const data=await r.json();if(!r.ok||!data.ok)throw Error(data.error||'unavailable');return data}
function showSession(account){identity=account&&['organizer','reviewer'].includes(account.role)?account:null;$('staff-session').hidden=!identity;$('staff-email-form').hidden=Boolean(identity);$('staff-code-form').hidden=true;$('staff-vote-link').hidden=identity?.role!=='organizer';$('staff-code').value='';translated()}
function clearProof(){token='';buttons()}
async function human(){const current=++epoch;clearProof();message('human');try{const config=await api('staff-login-config');if(config.required!==true||!config.siteKey)throw Error();const mount=()=>{if(current!==epoch||!window.turnstile)return;if(widget!==null)window.turnstile.remove?.(widget);$('staff-human').replaceChildren();widget=window.turnstile.render($('staff-human'),{sitekey:config.siteKey,action:'ghv_staff_login',callback:value=>{if(current!==epoch)return;token=typeof value==='string'?value:'';buttons()},'expired-callback':()=>{if(current===epoch){clearProof();message('human')}},'error-callback':()=>{if(current===epoch){clearProof();message('failed')}}})};if(window.turnstile)mount();else{window.staffWidgetReady=mount;const previous=document.querySelector('script[data-staff-widget]');previous?.remove();const script=document.createElement('script');script.dataset.staffWidget='true';script.src='https://challenges.cloudflare.com/turnstile/v0/api.js?onload=staffWidgetReady&render=explicit';script.onerror=()=>{if(current===epoch){clearProof();message('failed')}};document.head.append(script)}}catch{message('failed')}}
async function perform(action){if(busy)return;busy=true;buttons();try{await action()}catch(e){if(e.message==='login_required'){challenge=null;showSession(null);await human();message('signedout')}else message(e.message==='expired_or_invalid_code'?'invalid':'failed')}finally{busy=false;buttons()}}
$('staff-email-form').onsubmit=e=>{e.preventDefault();if(!token||busy)return;const proof=token;clearProof();perform(async()=>{const data=await api('request-code',{email:$('staff-email').value.trim(),role:$('staff-role').value,turnstile_token:proof});challenge=data.challenge_id;epoch++;$('staff-email-form').hidden=true;$('staff-code-form').hidden=false;message('sent');$('staff-code').focus()}).finally(()=>{if(!$('staff-email-form').hidden)human()})};
$('staff-code-form').onsubmit=e=>{e.preventDefault();perform(async()=>{await api('verify-code',{challenge_id:challenge,code:$('staff-code').value});challenge=null;showSession((await api('me')).account);message('signed')})};
$('staff-change').onclick=()=>{challenge=null;$('staff-code').value='';$('staff-code-form').hidden=true;$('staff-email-form').hidden=false;human()};
$('staff-retry').onclick=human;
$('staff-logout').onclick=()=>perform(async()=>{await api('logout',{});challenge=null;showSession(null);await human();message('signedout')});
$('staff-language').onchange=()=>{lang=$('staff-language').value;translated();if(!identity&&$('staff-code-form').hidden)human()};
translated();api('me').then(data=>{showSession(data.account);if(identity)message('signed');else human()}).catch(()=>{showSession(null);human()});
})();
